+    private IntegrityResult analyzeIntegrity(Properties properties) {
+        List<Entry> entries = new ArrayList<>();
+        for (String description : properties.stringPropertyNames()) {
+            entries.add(new Entry(description, properties.getProperty(description)));
+        }
+        Collections.sort(entries, Comparator.comparing(entry -> entry.description));
+
+        Map<String, List<Entry>> sameNames = new HashMap<>();
+        Map<String, List<Entry>> derivedNames = new HashMap<>();
+        for (Entry entry : entries) {
+            sameNames.computeIfAbsent(entry.fileName, ignored -> new ArrayList<>()).add(entry);
+            entry.resolution = resolveEntryFile(entry.fileName);
