+            for (Path file : files) {
+                if (STORED_RULES_FILE_NAME.equals(file.getFileName().toString())) {
+                    continue;
+                }
+                ResolvedPath candidate = resolvePath(file);
+                if (!candidate.isRegularFileDirectlyInFolder()) {
+                    continue;
+                }
+                boolean owned = false;
+                for (Entry entry : entries) {
+                    if (entry.resolution.realPath != null && sameFile(entry.resolution.realPath, candidate.realPath)) {
