+            try {
+                Path real = normalized.toRealPath();
+                boolean regular = Files.isRegularFile(real, LinkOption.NOFOLLOW_LINKS);
+                boolean direct = real.getParent() != null && real.getParent().equals(realStoreFolder);
+                return new ResolvedPath(normalized, real, regular, direct, true);
+            } catch (IOException | SecurityException e) {
+                return new ResolvedPath(normalized, null, false, false, true);
+            }
+        }
+        boolean direct = false;
+        try {
+            Path parent = normalized.getParent();
+            direct = parent != null && parent.toRealPath().equals(realStoreFolder);
+        } catch (IOException | SecurityException ignored) {
+            // A missing target with an unresolved parent is not a direct store file.
+        }
+        return new ResolvedPath(normalized, null, false, direct, false);
+    }
