+    private boolean containsNoViolations(Path file) {
+        try {
+            byte[] bytes = Files.readAllBytes(file);
+            String text = new String(bytes, UTF_8);
+            if (text.isEmpty()) {
+                return true;
+            }
+            boolean onlyLineBreaks = true;
+            for (int i = 0; i < text.length(); i++) {
+                if (text.charAt(i) != '\n' && text.charAt(i) != '\r') {
+                    onlyLineBreaks = false;
+                    break;
+                }
+            }
+            return onlyLineBreaks;
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException("Cannot read violation file " + file, e);
+        }
+    }
