+    private void deleteEntryFile(ResolvedPath resolution) {
+        try {
+            if (resolution.realPath != null) {
+                Files.deleteIfExists(resolution.realPath);
+            }
+            if (Files.isSymbolicLink(resolution.path)) {
+                Files.deleteIfExists(resolution.path);
+            } else if (resolution.realPath == null && resolution.existsInAnyForm()) {
+                Files.deleteIfExists(resolution.path);
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException("Cannot delete resolved violation file " + resolution.path, e);
+        }
+    }
