    private static final class IntegrityResult {
        private final List<Entry> entries;
        private final List<String> unownedFiles;

        private IntegrityResult(List<Entry> entries, List<String> unownedFiles) {
            this.entries = entries;
            this.unownedFiles = unownedFiles;
        }

        private boolean hasProblems() {
            for (Entry entry : entries) {
                if (entry.broken || entry.resolved || entry.shared || entry.misplaced || entry.colliding || entry.occupied) {
                    return true;
                }
            }
            return !unownedFiles.isEmpty();
        }

        private String report() {
            StringBuilder result = new StringBuilder("Violation store integrity check failed");
            appendEntries(result, "broken entries", entries, entry -> entry.broken);
            appendEntries(result, "resolved entries", entries, entry -> entry.resolved);
            appendEntries(result, "shared entries", entries, entry -> entry.shared);
            appendFiles(result, "unowned files", unownedFiles);
            appendEntries(result, "misplaced entries", entries, entry -> entry.misplaced);
            appendEntries(result, "colliding entries", entries, entry -> entry.colliding);
            appendEntries(result, "occupied entries", entries, entry -> entry.occupied);
            return result.toString();
        }

        private void appendEntries(StringBuilder result, String heading, List<Entry> entries, EntryCondition condition) {
            List<Entry> matching = entries.stream().filter(condition::matches).collect(toList());
            if (!matching.isEmpty()) {
                result.append("\n").append(heading).append(":");
                for (Entry entry : matching) {
                    result.append("\n  ").append(entry.description).append(" -> ").append(entry.fileName);
                }
            }
        }

        private void appendFiles(StringBuilder result, String heading, List<String> files) {
            if (!files.isEmpty()) {
                result.append("\n").append(heading).append(":");
                for (String file : files) {
                    result.append("\n  ").append(file);
                }
            }
        }
    }

    @FunctionalInterface
    private interface EntryCondition {
        boolean matches(Entry entry);
    }

    /**
     * Allows to adjust the rule violation file names of {@link TextFileBasedViolationStore}.
     */
    @FunctionalInterface
    @PublicAPI(usage = INHERITANCE)
    public interface RuleViolationFileNameStrategy {
        /**
